sm.slope_sweep(d)
b('Slope of the line through (x₁, y₁) and (x₂, y₂)?', r'\(m = \dfrac{y_2 - y_1}{x_2 - x_1}\)' + ', x₁ ≠ x₂ (if x₁ = x₂ the line is vertical)')
b('Example 1: slopes through (3,−2)&(−1,4); (3,−2)&(7,−2); (3,−2)&(3,4); inclination 60°.', N('−3/2') + ';  ' + N('0') + ';  ' + X('undefined') + ';  ' + N('√3'))
