b('Condition for three points A, B, C to be collinear?', T('slope AB = slope BC') + ' (or area of ABC = 0)')
b('Angle between two lines with slopes m₁ and m₂?', r'\(\tan\theta = \left|\dfrac{m_1 - m_2}{1 + m_1m_2}\right|\)' + ' (acute angle); if 1 + m₁m₂ = 0 the lines are perpendicular')
sm.two_answers_angle(d)
b('Example 3: line through (−2, 6), (4, 8) ⟂ line through (8, 12), (x, 24). Find x.', 'm₁ = 1/3, m₂ = 12/(x − 8) → product −1 → x − 8 = −36 → ' + N('x = −28'))
b('Ex 9.1 Q5: slope of the line through the origin and the midpoint of (0, −4) and (8, 0)?', 'Midpoint (4, −2): slope ' + N('−1/2'))
b('Ex 9.1 Q6: show (4, 4), (3, 5), (−1, −1) form a right triangle without Pythagoras.', 'Slope of (4,4)→(3,5) is −1; slope of (4,4)→(−1,−1) is 1; product −1, so the right angle is at ' + N('(4, 4)'))
b('Ex 9.1 Q7: slope of a line making 30° with the positive y-axis (anticlockwise)?', 'Inclination = 90° + 30° = 120° → ' + N('m = tan 120° = −√3'))
b('Ex 9.1 Q8: show (−2,−1), (4,0), (3,3), (−3,2) form a parallelogram using slopes.', 'AB and DC both have slope 1/6; BC and AD both have slope −3. Opposite sides parallel ✓')
b('Ex 9.1 Q9: angle between the x-axis and the line through (3, −1) and (4, −2)?', 'm = −1 → inclination ' + N('135°') + ' (angle with the axis 45°)')
b('Ex 9.1 Q10: one slope is double the other; tan of the angle between them is 1/3. Slopes?', '|m|/(1 + 2m²) = 1/3 → 2m² − 3|m| + 1 = 0 → ' + N('(1, 2) or (½, 1)') + ' (or their negatives)')
b('Ex 9.3 Q8: angle between √3x + y = 1 and x + √3y = 1.', 'm₁ = −√3, m₂ = −1/√3: tan θ = |(−√3 + 1/√3)/(1 + 1)| = 1/√3 → ' + N('30°') + ' (and 150°)')
b('Ex 9.3 Q9: line through (h, 3), (4, 1) is ⟂ to 7x − 9y − 19 = 0. Find h.', 'Slope needed −9/7: (1 − 3)/(4 − h) = −9/7 → ' + N('h = 22/9'))
b('Ex 9.3 Q11: two lines through (2, 3) meet at 60°; one has slope 2. The other?', '|(m − 2)/(1 + 2m)| = √3 → ' + N('m = −(8 + 5√3)/11') + ' or ' + N('m = (5√3 − 8)/11') + ' (two lines, one each side)')
b('Misc Q18: y = 3x + 1 and 2y = x + 3 are equally inclined to y = mx + 4. Find m.', 'Equal angles: |(m − 3)/(1 + 3m)| = |(m − ½)/(1 + m/2)|; the non-trivial case gives 7m² − 2m − 7 = 0 → ' + N('m = (1 ± 5√2)/7'))
b('Misc Q12: line through the origin at angle θ to y = mx + c?', N('y = ((m ± tan θ)/(1 ∓ m tan θ)) x'))

# ---------------------------------------------------------------- 9.3 Forms of the equation
d.sec('9.3-equations-of-a-line')
b('Horizontal and vertical lines at distance a from the axes?', 'Horizontal: ' + T('y = ±a') + '; vertical: ' + T('x = ±b'))
